export class FetchError extends Error {
  constructor(
    message: string,
    public code?: string,
    options?: ErrorOptions,
  ) {
    super(message, options);
    this.name = 'FetchError';
  }
}

/**
 * Error thrown when an attempt is made to access a private, reserved, or
 * otherwise non-routable network address.
 */
export class PrivateIpError extends Error {
  constructor(message = 'Access to private network is blocked') {
    super(message);
    this.name = 'PrivateIpError';
  }
}

/**
 * Parses a dotted-decimal IPv4 string into its four octets.
 * Returns null if the string is not a valid IPv4 address.
 */
function parseIpv4(address: string): number[] | null {
  const parts = address.split('.');
  if (parts.length !== 4) {
    return null;
  }
  const octets: number[] = [];
  for (const part of parts) {
    if (!/^\d{1,3}$/.test(part)) {
      return null;
    }
    const value = Number(part);
    if (value < 0 || value > 255) {
      return null;
    }
    octets.push(value);
  }
  return octets;
}

/**
 * Determines whether a set of IPv4 octets falls within any private, reserved,
 * or non-routable range as defined by RFC 1918 and RFC 6890.
 */
function isPrivateIpv4(octets: number[]): boolean {
  const [a, b, c] = octets;

  // 0.0.0.0/8 - "this" network
  if (a === 0) return true;
  // 10.0.0.0/8 - private
  if (a === 10) return true;
  // 100.64.0.0/10 - carrier-grade NAT
  if (a === 100 && b >= 64 && b <= 127) return true;
  // 127.0.0.0/8 - loopback
  if (a === 127) return true;
  // 169.254.0.0/16 - link-local
  if (a === 169 && b === 254) return true;
  // 172.16.0.0/12 - private
  if (a === 172 && b >= 16 && b <= 31) return true;
  // 192.0.0.0/24 - IETF protocol assignments
  if (a === 192 && b === 0 && c === 0) return true;
  // 192.0.2.0/24 - TEST-NET-1 (documentation)
  if (a === 192 && b === 0 && c === 2) return true;
  // 192.88.99.0/24 - 6to4 relay anycast
  if (a === 192 && b === 88 && c === 99) return true;
  // 192.168.0.0/16 - private
  if (a === 192 && b === 168) return true;
  // 198.18.0.0/15 - benchmarking
  if (a === 198 && (b === 18 || b === 19)) return true;
  // 198.51.100.0/24 - TEST-NET-2 (documentation)
  if (a === 198 && b === 51 && c === 100) return true;
  // 203.0.113.0/24 - TEST-NET-3 (documentation)
  if (a === 203 && b === 0 && c === 113) return true;
  // 224.0.0.0/4 - multicast
  if (a >= 224 && a <= 239) return true;
  // 240.0.0.0/4 - reserved (including 255.255.255.255 broadcast)
  if (a >= 240) return true;

  return false;
