    return dotted[1];
  }

  // ::ffff:a9fe:0101 (hexadecimal embedded form)
  const hex = lower.match(/^::ffff:([0-9a-f]{1,4}):([0-9a-f]{1,4})$/);
  if (hex) {
    const high = parseInt(hex[1], 16);
    const low = parseInt(hex[2], 16);
    const b1 = (high >> 8) & 0xff;
    const b2 = high & 0xff;
    const b3 = (low >> 8) & 0xff;
    const b4 = low & 0xff;
    return `${b1}.${b2}.${b3}.${b4}`;
  }

  return null;
}

/**
 * Returns the value of the first 16-bit group (hextet) of an IPv6 address, or
 * null if it cannot be determined (e.g. the address begins with "::").
 */
function ipv6FirstHextet(address: string): number | null {
  const firstGroup = address.split('::')[0].split(':')[0];
  if (!/^[0-9a-f]{1,4}$/.test(firstGroup)) {
    return null;
  }
  return parseInt(firstGroup, 16);
}

